SELECT * FROM stores_d;
--WITH cte AS(SELECT store, SUM(sales) AS tot_sales FROM stores_d GROUP BY 1) SELECT store, tot_sales, tot_sales :: NUMERIC/ (SELECT SUM(sales) FROM stores_d) :: NUMERIC * 100 AS sales_pct FROM cte WHERE tot_sales >= (SELECT AVG(sales) FROM stores_d) ORDER BY 2 DESC; 
--WITH cte AS(SELECT storetype, SUM(sales) AS tot_sales, AVG(sales) AS avg_daily_sales, SUM(customers) AS tot_customers, AVG(customers) AS boot FROM stores_d GROUP BY 1) SELECT storetype, tot_sales, avg_daily_sales, tot_customers, avg_daily_sales / boot AS avg_sales_per_cus FROM cte ORDER BY 1 ASC; 
--WITH cte AS(SELECT store, storetype, SUM(sales) AS tot_sales FROM stores_d GROUP BY 1, 2) SELECT store, storetype, tot_sales, (SELECT AVG(tot_sales) :: NUMERIC FROM cte) AS avg_avg_daily_sales FROM cte WHERE tot_sales <= (SELECT AVG(tot_sales) :: NUMERIC FROM cte) ORDER BY 1 ASC;  
--WITH cte AS(SELECT store, month, SUM(sales) AS tot_sales_month FROM stores_d group by 1, 2), cte1 AS(SELECT store, month, tot_sales_month,  RANK() OVER(PARTITION BY store ORDER BY tot_sales_month DESC) AS rn1, RANK() OVER(PARTITION BY store ORDER BY tot_sales_month ASC) AS rn2 FROM cte), cte2 as (SELECT store, month, tot_sales_month, rn1, rn2 FROM cte1 WHERE rn1 = 1 OR rn2 = 1), cte3 AS(SELECT store, month, ABS(tot_sales_month - LAG(tot_sales_month) OVER(PARTITION BY store ORDER BY month)) AS sales_month_diff FROM cte2) SELECT * FROM cte3 WHERE sales_month_diff IS NOT NULL;    
--WITH cte AS(SELECT store, month, AVG(sales) AS avg_month_sales, AVG(sales) :: numeric / AVG(customers) :: numeric AS avg_sales_per_cus FROM stores_d GROUP BY 1, 2), mm AS(SELECT store, MAX(MONTH) AS max_month FROM cte GROUP BY 1), c AS(SELECT store, AVG(avg_month_sales) AS first_month_sales, AVG(avg_sales_per_cus) AS first_month_s_p_c from cte where month = 1 GROUP BY 1), c1 AS(SELECT cte.store, SUM(cte.avg_month_sales) AS last_months_sales, SUM(cte.avg_sales_per_cus) AS last_months_s_p_c from cte LEFT JOIN mm ON mm.store = cte.store where cte.month >= mm.max_month - 2  GROUP BY 1), cte1 as (SELECT c.store, c.first_month_sales, c1.last_months_sales, c.first_month_s_p_c, c1.last_months_s_p_c, last_months_sales - first_month_sales AS sales_diff, last_months_s_p_c - first_month_s_p_c AS sales_per_cus_diff FROM c LEFT JOIN c1 ON c.store = c1.store) SELECT *, (SELECT AVG(sales_diff) FROM cte1) AS avg_sales_diff, (SELECT AVG(sales_per_cus_diff) FROM cte1) AS avg_sales_per_cus_diff FROM cte1 WHERE sales_per_cus_diff >= (SELECT AVG(sales_per_cus_diff) FROM cte1) AND sales_diff >= (SELECT AVG(sales_diff) FROM cte1) ORDER BY sales_diff DESC, sales_per_cus_diff DESC;  
--WITH cte AS(SELECT storetype, AVG(sales) FILTER(WHERE promo2 = 1) AS avg_sales_promo, AVG(sales) FILTER(WHERE promo2 = 0) AS avg_sales_non_promo FROM stores_d group by 1) SELECT *, avg_sales_promo / (SELECT SUM(avg_sales_promo) FROM cte) * 100 AS sales_promo_pct FROM cte ORDER BY 4 DESC
--WITH cte AS(SELECT store, AVG(sales) FILTER(WHERE promo2 = 1) AS avg_sales_promo, AVG(sales) FILTER(WHERE promo2 = 0) AS avg_sales_non_promo FROM stores_d group by 1) SELECT *, avg_sales_promo / (SELECT SUM(avg_sales_promo) FROM cte) * 100 AS sales_promo_pct FROM cte WHERE avg_sales_promo IS NOT NULL AND avg_sales_non_promo IS NOT NULL ORDER BY 4 DE
--WITH cte AS(SELECT storetype,  AVG(sales) FILTER (WHERE promo2=1) / AVG(customers) FILTER(WHERE promo2=1) AS promo_sales_per_customer, AVG(sales) FILTER (WHERE promo2=0) / AVG(customers) FILTER(WHERE promo2=0) AS non_promo_sales_per_customer  FROM stores_d GROUP BY 1) SELECT *, (CASE WHEN promo_sales_per_customer > non_promo_sales_per_customer THEN True ELSE FALSE END) AS is_promo_highter FROM cte
--SELECT storetype, assortment, COALESCE(AVG(sales) FILTER (WHERE promo2 = 1), 0) AS promp_sales_avg FROM stores_d group by 1, 2 ORDER BY 3 DESC LIMIT 1
--WITH cte AS(SELECT competitiondistance, COALESCE(AVG(sales), 0) AS sales_avg FROM stores_d GROUP BY 1), cte1 AS(SELECT *, LAG(competitiondistance) over(ORDER BY competitiondistance) AS pre_competitiondistance, LAG(sales_avg) over(ORDER BY competitiondistance) AS pre_sales_avg FROM cte), cte2 AS(SELECT *, sales_avg - pre_sales_avg AS sales_diff from cte1 WHERE pre_sales_avg IS NOT NULL) select * FROM cte2 ORDER BY sales_diff DESC LIMIT 1
--WITH cte AS(SELECT storetype, AVG(sales) FILTER(WHERE promo2 = 1) AS avg_sales_promo, AVG(sales) FILTER(WHERE promo2 = 0) AS avg_sales_non_promo FROM stores_d group by 1) SELECT *, avg_sales_promo / (SELECT SUM(avg_sales_promo) FROM cte) * 100 AS sales_promo_pct FROM cte ORDER BY 4 DESC
--WITH cte AS(SELECT store, AVG(sales) FILTER(WHERE promo2 = 1) AS avg_sales_promo, AVG(sales) FILTER(WHERE promo2 = 0) AS avg_sales_non_promo FROM stores_d group by 1) SELECT *, avg_sales_promo / (SELECT SUM(avg_sales_promo) FROM cte) * 100 AS sales_promo_pct FROM cte WHERE avg_sales_promo IS NOT NULL AND avg_sales_non_promo IS NOT NULL ORDER BY 4
--WITH cte AS(select store, month, AVG(sales) AS sales_avg FROM stores_d GROUP BY 1, 2),cte1 AS (SELECT *, LAG(month) OVER(PARTITION BY store  ORDER BY month) AS pre_month, LAG(sales_avg) OVER(PARTITION BY store ORDER BY month) AS pre_sales_avg FROM cte), cte2 AS(SELECT *, (sales_avg - pre_sales_avg) / pre_sales_avg * 100  AS sales_avg_growth FROM cte1 WHERE pre_month IS NOT NULL), cte3 AS(SELECT *, DENSE_RANK() OVER(PARTITION BY store ORDER BY sales_avg_growth DESC) AS rn1, DENSE_RANK() OVER(PARTITION BY store ORDER BY sales_avg_growth ASC) AS rn2 FROM cte2) SELECT * FROM cte3 WHERE rn1 = 1 OR rn2 = 1;                                                
--WITH cte AS(SELECT year, store, SUM(sales) AS tot_sales FROM stores_d group by 1, 2), cte1 AS(SELECT *, LAG(year) OVER(PARTITION BY store ORDER BY year) AS pre_year, LAG(tot_sales) OVER(PARTITION BY store ORDER BY year) AS pre_tot_sales FROM cte) SELECT *, (CASE WHEN tot_sales > pre_tot_sales THEN 'Improved' WHEN tot_sales < pre_tot_sales THEN 'Did not improved' ELSE 'No change' END) AS is_improved FROM cte1 WHERE pre_tot_sales IS NOT NULL;
--WITH cte AS(SELECT storetype, AVG(sales) FILTER(WHERE promo2 = 1) AS avg_sales_promo, AVG(sales) FILTER(WHERE promo2 = 0) AS avg_sales_non_promo FROM stores_d group by 1) SELECT *, avg_sales_promo / (SELECT SUM(avg_sales_promo) FROM cte) * 100 AS sales_promo_pct FROM cte ORDER BY 4 DESC
--WITH cte AS(SELECT store, AVG(sales) FILTER(WHERE promo2 = 1) AS avg_sales_promo, AVG(sales) FILTER(WHERE promo2 = 0) AS avg_sales_non_promo FROM stores_d group by 1) SELECT *, avg_sales_promo / (SELECT SUM(avg_sales_promo) FROM cte) * 100 AS sales_promo_pct FROM cte WHERE avg_sales_promo IS NOT NULL AND avg_sales_non_promo IS NOT NULL ORDER BY 4 DE
--(SELECT year, store, sum(sales) AS tot_sales FROM stores_d GROUP BY 1, 2), cte1 AS (SELECT *, LAG(year) OVER(PARTITION BY store ORDER BY year) AS pre_year, LAG(tot_sales) OVER(PARTITION BY store ORDER BY year) AS pre_tot_sales FROM cte), cte2 AS(SELECT *, (CASE WHEN tot_sales > pre_tot_sales THEN 'Improved' WHEN tot_sales < pre_tot_sales THEN 'Did NOT Improved' ELSE 'Still' END) AS is_improved) FROM cte1 OREDR 
--WITH cte AS(SELECT  store, year, month, SUM(sales) AS tot_sales FROM stores_d GROUP BY 1, 2, 3), cte1 AS (SELECT *, LAG(tot_sales) OVER(PARTITION BY  store, month order by YEAR) as pre_tot_sales from cte), cte2 AS(SELECT *, ROW_NUMBER() OVER(PARTITION BY store ORDER BY year desc) AS rn , tot_sales - pre_tot_sales AS diff  FROM cte1 WHERE tot_sales :: NUMERIC * 75 / 100 >= pre_tot_sales::numeric) SELECT * FROM cte2 WHERE rn =1 ordEr by diff DESC, store asc 










